compile.workshop:
variables {
    global:
        0: g
    player:
        0: p
}

//Optimize for size enabled
rule ("size rewrites") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Create Beam Effect(Event Player, Grapple Beam, Up, Down, Null, None);
        Create Progress Bar HUD Text(Event Player, 0, Char In String(Empty Array, False), Left, 3, Null, Null, Color, Default Visibility);
        Create Progress Bar HUD Text(Event Player, Global.g, Global.g, Left, 3, Color(Red), Color(Red), Color, Default Visibility);
        Set Global Variable(g, String Split(Custom String("abc"), Empty Array));
        Create HUD Text(Event Player, Null, Global.g, Null, Left, 3, Null, Color(Yellow), Null, Visible To and String, Default Visibility);
    }
}

